package com.casegen.ai.proposal.review;
import java.util.*;
import org.springframework.stereotype.Component;
@Component public class AiProposalDependencyGraph {
 public List<String> topologicalOrder(List<AiReviewItem> items,Map<String,Set<String>> dependencies){Map<String,AiReviewItem> byRef=new HashMap<>();Map<String,Integer> original=new HashMap<>();for(int i=0;i<items.size();i++){byRef.put(items.get(i).clientRef(),items.get(i));original.put(items.get(i).clientRef(),i);}Map<String,Integer> degree=new HashMap<>();Map<String,List<String>> outgoing=new HashMap<>();for(String ref:byRef.keySet())degree.put(ref,0);dependencies.forEach((item,deps)->{for(String dep:deps){if(!byRef.containsKey(dep))throw error("dependency does not exist: "+dep);degree.put(item,degree.get(item)+1);outgoing.computeIfAbsent(dep,k->new ArrayList<>()).add(item);}});Comparator<String> comparator=Comparator.comparingInt((String ref)->priority(byRef.get(ref).proposalType())).thenComparingInt(original::get).thenComparing(ref->ref);PriorityQueue<String> ready=new PriorityQueue<>(comparator);degree.forEach((k,v)->{if(v==0)ready.add(k);});List<String> result=new ArrayList<>();while(!ready.isEmpty()){String current=ready.remove();result.add(current);for(String next:outgoing.getOrDefault(current,List.of())){int value=degree.merge(next,-1,Integer::sum);if(value==0)ready.add(next);}}if(result.size()!=items.size())throw error("proposal dependency cycle");return result;}
 private int priority(AiReviewProposalType type){return switch(type){case ADD_CLASSIFIER->0;case ADD_ATTRIBUTE,ADD_OPERATION,UPDATE_CLASSIFIER,UPDATE_ATTRIBUTE->1;default->2;};}
 private AiReviewValidationException error(String m){return new AiReviewValidationException(AiReviewValidationErrorCode.PROPOSAL_DEPENDENCY_CYCLE,m);}}
